import React, { useRef, useState, useEffect } from 'react';
import emailjs from '@emailjs/browser';
import PhoneInput, { isPossiblePhoneNumber } from 'react-phone-number-input';
import { ToastContainer, toast } from 'react-toastify';
import 'react-phone-number-input/style.css';
import 'react-toastify/dist/ReactToastify.css';
import './contact.css';
import { trackPortfolioEvent } from '../../Analytics/plausibleAnalyticsUtils';
const Modal = ({ isOpen, onClose, children }) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center">
      <div className="bg-white p-5 rounded-lg shadow-lg relative l:w-96	w-72 ml-0 md:w-96 md:ml-24 sm:p-6 md:p-8 lg:p-10 xl:p-12">
        <button
          onClick={onClose}
          className="absolute top-2 right-4 text-gray-600 text-lg"
        >
          &times;
        </button>
        {children}
      </div>
    </div>
  );
};

const Contact = () => {
  const [input, setInput] = useState('');
  const [phoneNumber, setPhoneNumber] = useState();
  const [phoneNumberError, setPhoneNumberError] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [message, setMessage] = useState('');

  const maxCharacters = 500;
  const getPhoneNumberError = (value) =>
    value && !isPossiblePhoneNumber(value)
      ? 'This number has an invalid length for the selected country.'
      : '';
  const handlePhoneNumberChange = (value) => {
    setPhoneNumber(value);
    setPhoneNumberError(getPhoneNumberError(value));
  };
  const handleCloseModal = () => {
    setIsModalOpen(!isModalOpen);
  };
  const inputHandler = (e) => {
    setInput(e.target.value);
  };
  const form = useRef();
  const useFocus = useRef(null);
  const focusInput = () => {
    useFocus.current?.focus();
  };
  useEffect(() => {
    focusInput(); //focus onload the page.
  }, []);

  const sendEmail = (e) => {
    e.preventDefault();
    const phoneError = getPhoneNumberError(phoneNumber);
    if (!phoneNumber || phoneError) {
      setPhoneNumberError(phoneError);
      toast.error(
        'Please enter a phone number with a valid length for its country.'
      );
      return;
    }
    //Focus input onSubmit
    focusInput();
    setInput('');
    emailjs
      .sendForm(
        'service_7mcn71l',
        'template_35k6w7v',
        form.current,
        '_NtaKoGAAqdPTeVWv'
      )
      .then(
        (result) => {
          if (result) {
            setIsModalOpen(true);
            trackPortfolioEvent('generate_lead', {
              lead_source: 'contact_form',
              form_status: 'success',
            });
            console.log(result.text);
            setMessage('successfully sent email.');
            // toast.success("Contact successfully sent!!!",{ autoClose: false });
          }
        },
        (error) => {
          toast.error('Please fill contact details correctly', +error.message);
          trackPortfolioEvent('contact_form_failure', {
            error_type: error?.text ? 'email_service' : 'network_or_unknown',
          });
          setMessage('You are having errors to submit a form.' + error.message);
        }
      );
    e.target.reset();
    setPhoneNumber(undefined);
    setPhoneNumberError('');
  };
  const numberofCharacters = maxCharacters - input.length;
  const hasInvalidPhoneNumberLength = Boolean(phoneNumberError);
  return (
    <section className="pb-10">
      <div className="flex flex-wrap md:px-4">
        <form
          className="p-8 md:mx-4 bg-white rounded-md shadow-md"
          ref={form}
          onSubmit={sendEmail}
          id="create-course-form"
        >
          <div className="m-3">
            <h3 className="text-2xl text-gray-800 font-bold mb-6 hover:text-indigo-400">
              Get in Touch
            </h3>
          </div>
          <ToastContainer />
          <div className="w-full flex flex-wrap">
            <div className="w-full md:w-1/2">
              <div className="m-3">
                <input
                  type="text"
                  ref={useFocus}
                  name="name"
                  maxlength="30"
                  placeholder="Your Name"
                  required
                  className="w-full border border-gray-800 rounded py-4 px-6 text-sm bg-white"
                />
              </div>
            </div>
            <div className="w-full md:w-1/2">
              <div className="m-3">
                <input
                  type="email"
                  required
                  name="email"
                  placeholder="Your Email"
                  className="w-full border border-gray-800 rounded py-4 px-6 text-sm bg-white"
                />
              </div>
            </div>
            <div className="w-full">
              <div className="m-3">
                <PhoneInput
                  className="contact-phone-input"
                  defaultCountry="US"
                  international
                  value={phoneNumber}
                  onChange={handlePhoneNumberChange}
                  required
                  placeholder="Phone Number"
                  aria-label="Phone Number"
                  aria-invalid={Boolean(hasInvalidPhoneNumberLength)}
                  aria-describedby={
                    hasInvalidPhoneNumberLength
                      ? 'phone-number-error'
                      : undefined
                  }
                />
                <input type="hidden" name="phone" value={phoneNumber || ''} />
                {hasInvalidPhoneNumberLength && (
                  <p
                    id="phone-number-error"
                    className="mt-2 text-sm text-red-600"
                    role="alert"
                  >
                    {phoneNumberError}
                  </p>
                )}
              </div>
            </div>
            <div className="w-full">
              <div className="m-3">
                <input
                  type="text"
                  name="subject"
                  maxlength="100"
                  required
                  placeholder="Subject"
                  className="w-full border border-gray-800 rounded py-4 px-6 text-sm bg-white"
                />
              </div>
            </div>
            <div className="w-full">
              <div className="m-3">
                <textarea
                  name="message"
                  required
                  placeholder="Your Message"
                  onChange={inputHandler}
                  rows="6"
                  maxLength="500"
                  className="w-full border border-gray-800 rounded py-4 px-6 text-sm bg-white"
                />
                <span className="charLeft">
                  {numberofCharacters} Characters
                </span>
              </div>
            </div>
            <div className="w-full">
              <div className="m-3 text-right">
                <input
                  type="submit"
                  value="Send"
                  className="rounded bg-purple-900 text-center border-0 py-3 px-6 text-white leading-7 tracking-wide hover:bg-purple-800 cursor-pointer"
                />
              </div>
            </div>
          </div>
        </form>
        <Modal isOpen={isModalOpen} onClose={handleCloseModal}>
          <div class="wrapper">
            <div class="circle">
              <div class="checkMark"></div>
            </div>
          </div>
          <h2 className="text-2xl font-bold mb-4 text-alignment">Success!!</h2>
          <p className="mb-4 text-alignment">{message}</p>
          <button
            onClick={handleCloseModal}
            className="sticky bg-green-900 text-white p-2 rounded float-right"
          >
            Close
          </button>
        </Modal>
      </div>
    </section>
  );
};

export default Contact;
